public class InnerGatewayHostSharedAlbConfigurationFactory(Action<Humidifier.ECS.GatewayTypes.HostSharedAlbConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.ECS.GatewayTypes.HostSharedAlbConfiguration>
{

    internal InnerGatewayGatewayAlbTestTrafficRulesFactory TestTrafficRulesFactory { get; set; }

    internal InnerGatewayGatewayElbNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    internal InnerGatewayGatewayElbAccessLogConfigurationFactory AccessLogsFactory { get; set; }

    protected override Humidifier.ECS.GatewayTypes.HostSharedAlbConfiguration Create()
    {
        var hostSharedAlbConfigurationResult = CreateHostSharedAlbConfiguration();
        factoryAction?.Invoke(hostSharedAlbConfigurationResult);

        return hostSharedAlbConfigurationResult;
    }

    private Humidifier.ECS.GatewayTypes.HostSharedAlbConfiguration CreateHostSharedAlbConfiguration()
    {
        var hostSharedAlbConfigurationResult = new Humidifier.ECS.GatewayTypes.HostSharedAlbConfiguration();

        return hostSharedAlbConfigurationResult;
    }
    public override void CreateChildren(Humidifier.ECS.GatewayTypes.HostSharedAlbConfiguration result)
    {
        base.CreateChildren(result);

        result.TestTrafficRules ??= TestTrafficRulesFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
        result.AccessLogs ??= AccessLogsFactory?.Build();
    }

} // End Of Class

